namespace sv_1a0dffbbfcbf46fdb339953f9ac92304.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@namespace sv_1a0dffbbfcbf46fdb339953f9ac92304.Components.Pages.Settings

<nav class="settings-sidebar">
    <ul class="settings-nav">
        @foreach (var section in Sections)
        {
            <li class="settings-nav-item @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionSelected.InvokeAsync(section)">
                <span class="settings-nav-icon">@GetIcon(section)</span>
                <span class="settings-nav-label">@section</span>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionSelected { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@namespace sv_1a0dffbbfcbf46fdb339953f9ac92304.Components.Pages.Settings
@using sv_1a0dffbbfcbf46fdb339953f9ac92304.Services

<div class="settings-section">
    <h2>Profile</h2>

    @if (ShowSuccess)
    {
        <div class="toast toast-success">Profile saved successfully!</div>
    }

    <div class="form-group avatar-group">
        <label>Avatar Preview</label>
        <div class="avatar-preview">
            @if (!string.IsNullOrWhiteSpace(_displayName))
            {
                <img src="@_avatarUrl" alt="Avatar" class="avatar-image" />
            }
            <span class="avatar-url-display">@_avatarUrl</span>
        </div>
    </div>

    <div class="form-group">
        <label for="displayName">Display Name</label>
        <input id="displayName" type="text" class="form-control" @bind="_displayName" />
    </div>

    <div class="form-group">
        <label for="email">Email</label>
        <input id="email" type="email" class="form-control" @bind="_email" />
    </div>

    <div class="form-group">
        <label for="bio">Bio</label>
        <textarea id="bio" class="form-control" rows="4" @bind="_bio"></textarea>
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAsync">Save Changes</button>
        <button class="btn btn-secondary" @onclick="Discard">Discard Changes</button>
    </div>
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";
    private bool ShowSuccess;

    protected override void OnParametersSet()
    {
        if (Profile is not null && !_initialized)
        {
            LoadFromProfile(Profile);
            _initialized = true;
        }
    }

    private bool _initialized;

    private void LoadFromProfile(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;
    }

    private async Task SaveAsync()
    {
        var updated = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await OnSave.InvokeAsync(updated);
        ShowSuccess = true;
        StateHasChanged();
        await Task.Delay(3000);
        ShowSuccess = false;
        StateHasChanged();
    }

    private void Discard()
    {
        if (Profile is not null)
        {
            LoadFromProfile(Profile);
        }
    }
}

@namespace sv_1a0dffbbfcbf46fdb339953f9ac92304.Components.Pages.Settings
@using sv_1a0dffbbfcbf46fdb339953f9ac92304.Services

<div class="settings-section">
    <h2>Notifications</h2>

    @if (ShowSuccess)
    {
        <div class="toast toast-success">Preferences saved successfully!</div>
    }

    <div class="toggle-group">
        <label class="toggle-label">
            <input type="checkbox" @bind="_emailNotifications" class="toggle-switch" />
            <span>Email Notifications</span>
        </label>
    </div>

    <div class="toggle-group">
        <label class="toggle-label">
            <input type="checkbox" @bind="_pushNotifications" class="toggle-switch" />
            <span>Push Notifications</span>
        </label>
    </div>

    <div class="toggle-group">
        <label class="toggle-label">
            <input type="checkbox" @bind="_weeklyDigest" class="toggle-switch" />
            <span>Weekly Digest</span>
        </label>
    </div>

    <h3>Muted Channels</h3>
    <div class="channel-list">
        @if (AvailableChannels is not null)
        {
            @foreach (var channel in AvailableChannels)
            {
                <label class="channel-item">
                    <input type="checkbox"
                           checked="@_mutedChannels.Contains(channel)"
                           @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                    <span>@channel</span>
                </label>
            }
        }
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAsync">Save Preferences</button>
    </div>
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public List<string>? AvailableChannels { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();
    private bool _initialized;
    private bool ShowSuccess;

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !_initialized)
        {
            _emailNotifications = Prefs.EmailNotifications;
            _pushNotifications = Prefs.PushNotifications;
            _weeklyDigest = Prefs.WeeklyDigest;
            _mutedChannels = new HashSet<string>(Prefs.MutedChannels);
            _initialized = true;
        }
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        var updated = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await OnSave.InvokeAsync(updated);
        ShowSuccess = true;
        StateHasChanged();
        await Task.Delay(3000);
        ShowSuccess = false;
        StateHasChanged();
    }
}

@namespace sv_1a0dffbbfcbf46fdb339953f9ac92304.Components.Pages.Settings
@using sv_1a0dffbbfcbf46fdb339953f9ac92304.Services

<div class="settings-section">
    <h2>Security</h2>

    @if (!string.IsNullOrEmpty(_message))
    {
        <div class="toast @(_isError ? "toast-error" : "toast-success")">@_message</div>
    }

    <!-- Change Password Panel -->
    <div class="expandable-panel">
        <button class="panel-header" @onclick="() => _passwordExpanded = !_passwordExpanded">
            <span>Change Password</span>
            <span class="expand-icon">@(_passwordExpanded ? "▼" : "▶")</span>
        </button>
        @if (_passwordExpanded)
        {
            <div class="panel-content">
                <div class="form-group">
                    <label for="currentPassword">Current Password</label>
                    <input id="currentPassword" type="password" class="form-control" @bind="_currentPassword" />
                </div>
                <div class="form-group">
                    <label for="newPassword">New Password</label>
                    <input id="newPassword" type="password" class="form-control" @bind="_newPassword" />
                </div>
                <div class="form-group">
                    <label for="confirmPassword">Confirm Password</label>
                    <input id="confirmPassword" type="password" class="form-control" @bind="_confirmPassword" />
                </div>
                <button class="btn btn-primary" @onclick="ChangePasswordAsync">Update Password</button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="toggle-group tfa-group">
        <label class="toggle-label">
            <input type="checkbox" checked="@_twoFactorEnabled" disabled class="toggle-switch" />
            <span>Two-Factor Authentication</span>
            <span class="status-indicator @(_twoFactorEnabled ? "status-on" : "status-off")">
                @(_twoFactorEnabled ? "Enabled" : "Disabled")
            </span>
        </label>
        @if (Settings?.LastPasswordChange is not null)
        {
            <p class="help-text">Last password change: @Settings.LastPasswordChange.Value.ToString("MMM dd, yyyy")</p>
        }
    </div>

    <!-- Active Sessions -->
    <h3>Active Sessions</h3>
    @if (Settings?.Sessions is not null && Settings.Sessions.Count > 0)
    {
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th>Action</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Settings.Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@session.LastActive.ToString("g")</td>
                        <td>
                            @if (session.Id != CurrentSessionId)
                            {
                                <button class="btn btn-danger btn-sm" @onclick="() => PromptRevoke(session)">
                                    Revoke
                                </button>
                            }
                            else
                            {
                                <span class="current-session-badge">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    }
    else
    {
        <p>No active sessions.</p>
    }

    <!-- Revoke Confirmation Dialog -->
    @if (_sessionToRevoke is not null)
    {
        <div class="modal-overlay" @onclick="CancelRevoke">
            <div class="modal-dialog" @onclick:stopPropagation="true">
                <h4>Revoke Session</h4>
                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in <strong>@_sessionToRevoke.Location</strong>?</p>
                <div class="modal-actions">
                    <button class="btn btn-danger" @onclick="ConfirmRevokeAsync">Revoke</button>
                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public SecuritySettings? Settings { get; set; }
    [Parameter] public string CurrentSessionId { get; set; } = "";
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }
    [Parameter] public EventCallback<(string currentPassword, string newPassword)> OnChangePassword { get; set; }

    private bool _passwordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _twoFactorEnabled;
    private ActiveSession? _sessionToRevoke;
    private string _message = "";
    private bool _isError;

    protected override void OnParametersSet()
    {
        if (Settings is not null)
        {
            _twoFactorEnabled = Settings.TwoFactorEnabled;
        }
    }

    private async Task ChangePasswordAsync()
    {
        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            ShowMessage("New password cannot be empty.", true);
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            ShowMessage("Passwords do not match.", true);
            return;
        }
        await OnChangePassword.InvokeAsync((_currentPassword, _newPassword));
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        ShowMessage("Password updated successfully.", false);
    }

    private void PromptRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }

    private async Task ConfirmRevokeAsync()
    {
        if (_sessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(_sessionToRevoke.Id);
