@namespace sv_1a0dffbbfcbf46fdb339953f9ac92304.Components.Pages.Settings
@using sv_1a0dffbbfcbf46fdb339953f9ac92304.Services

<div class="settings-section">
    <h2>Notifications</h2>

    @if (ShowSuccess)
    {
        <div class="toast toast-success">Preferences saved successfully!</div>
    }

    <div class="toggle-group">
        <label class="toggle-label">
            <input type="checkbox" @bind="_emailNotifications" class="toggle-switch" />
            <span>Email Notifications</span>
        </label>
    </div>

    <div class="toggle-group">
        <label class="toggle-label">
            <input type="checkbox" @bind="_pushNotifications" class="toggle-switch" />
            <span>Push Notifications</span>
        </label>
    </div>

    <div class="toggle-group">
        <label class="toggle-label">
            <input type="checkbox" @bind="_weeklyDigest" class="toggle-switch" />
            <span>Weekly Digest</span>
        </label>
    </div>

    <h3>Muted Channels</h3>
    <div class="channel-list">
        @if (AvailableChannels is not null)
        {
            @foreach (var channel in AvailableChannels)
            {
                <label class="channel-item">
                    <input type="checkbox"
                           checked="@_mutedChannels.Contains(channel)"
                           @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                    <span>@channel</span>
                </label>
            }
        }
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAsync">Save Preferences</button>
    </div>
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public List<string>? AvailableChannels { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();
    private bool _initialized;
    private bool ShowSuccess;

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !_initialized)
        {
            _emailNotifications = Prefs.EmailNotifications;
            _pushNotifications = Prefs.PushNotifications;
            _weeklyDigest = Prefs.WeeklyDigest;
            _mutedChannels = new HashSet<string>(Prefs.MutedChannels);
            _initialized = true;
        }
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        var updated = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await OnSave.InvokeAsync(updated);
        ShowSuccess = true;
        StateHasChanged();
        await Task.Delay(3000);
        ShowSuccess = false;
        StateHasChanged();
    }
}

