@namespace sv_1a0dffbbfcbf46fdb339953f9ac92304.Components.Pages.Settings

<div class="appearance-preview @ThemeClass @FontClass @(CompactMode ? "compact" : "")">
    <div class="preview-header">Preview</div>
    <div class="preview-content">
        <p class="preview-title">Sample Heading</p>
        <p class="preview-text">This is how your content will look with the selected appearance settings.</p>
        <div class="preview-card">
            <span class="preview-badge">Notification</span>
            <span>You have 3 new messages</span>
        </div>
    </div>
</div>

@code {
    [Parameter] public string Theme { get; set; } = "Light";
    [Parameter] public string FontSize { get; set; } = "Medium";
    [Parameter] public bool CompactMode { get; set; }

    private string ThemeClass => $"preview-theme-{Theme.ToLowerInvariant()}";
    private string FontClass => $"preview-font-{FontSize.ToLowerInvariant()}";
}

@namespace sv_1a0dffbbfcbf46fdb339953f9ac92304.Components.Pages.Settings
@using sv_1a0dffbbfcbf46fdb339953f9ac92304.Services

<div class="settings-section">
    <h2>Appearance</h2>

    @if (ShowSuccess)
    {
        <div class="toast toast-success">Appearance settings saved!</div>
    }

    <div class="form-group">
        <label>Theme</label>
        <div class="radio-group">
            @foreach (var theme in new[] { "Light", "Dark", "System" })
            {
                <label class="radio-label">
                    <input type="radio" name="theme" value="@theme"
                           checked="@(_theme == theme)"
                           @onchange="() => _theme = theme" />
                    <span>@theme</span>
                </label>
            }
        </div>
    </div>

    <div class="form-group">
        <label>Font Size</label>
        <div class="radio-group">
            @foreach (var size in new[] { "Small", "Medium", "Large" })
            {
                <label class="radio-label">
                    <input type="radio" name="fontSize" value="@size"
                           checked="@(_fontSize == size)"
                           @onchange="() => _fontSize = size" />
                    <span>@size</span>
                </label>
            }
        </div>
    </div>

    <div class="form-group">
        <label for="language">Language</label>
        <select id="language" class="form-control" @bind="_language">
            <option value="en">English</option>
            <option value="es">Español</option>
            <option value="fr">Français</option>
            <option value="de">Deutsch</option>
            <option value="ja">日本語</option>
            <option value="zh">中文</option>
        </select>
    </div>

    <div class="toggle-group">
        <label class="toggle-label">
            <input type="checkbox" @bind="_compactMode" class="toggle-switch" />
            <span>Compact Mode</span>
        </label>
    </div>

    <AppearancePreview Theme="@_theme" FontSize="@_fontSize" CompactMode="@_compactMode" />

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAsync">Save</button>
    </div>
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;
    private bool _initialized;
    private bool ShowSuccess;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !_initialized)
        {
            _theme = Settings.Theme;
            _fontSize = Settings.FontSize;
            _language = Settings.Language;
            _compactMode = Settings.CompactMode;
            _initialized = true;
        }
    }

    private async Task SaveAsync()
    {
        var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await OnSave.InvokeAsync(updated);
        ShowSuccess = true;
        StateHasChanged();
        await Task.Delay(3000);
        ShowSuccess = false;
        StateHasChanged();
    }
}

