+
+.tfa-group .help-text {
+    margin: 0.25rem 0 0 1.6rem;
+    font-size: 0.8rem;
+    color: #6b7280;
+}
+
+/* Sessions table */
+.sessions-table {
+    width: 100%;
+    border-collapse: collapse;
+    font-size: 0.9rem;
+}
+
+.sessions-table th,
+.sessions-table td {
+    padding: 0.6rem 0.75rem;
+    text-align: left;
+    border-bottom: 1px solid #e2e8f0;
+}
+
+.sessions-table th {
+    background: #f8fafc;
+    font-weight: 600;
+    color: #475569;
+}
+
+.current-session-badge {
+    font-size: 0.75rem;
+    background: #eff6ff;
+    color: #2563eb;
+    padding: 0.15rem 0.5rem;
+    border-radius: 4px;
+}
+
+/* Modal */
+.modal-overlay {
+    position: fixed;
+    inset: 0;
+    background: rgba(0, 0, 0, 0.5);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1000;
+}
+
+.modal-dialog {
+    background: #fff;
+    padding: 1.5rem;
+    border-radius: 8px;
+    max-width: 400px;
+    width: 90%;
+    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
+}
+
+.modal-dialog h4 {
+    margin: 0 0 0.75rem;
+    color: #1e293b;
+}
+
+.modal-dialog p {
+    color: #475569;
+    font-size: 0.9rem;
+    margin-bottom: 1.25rem;
+}
+
+.modal-actions {
+    display: flex;
+    gap: 0.75rem;
+    justify-content: flex-end;
+}
+
+/* Radio groups */
+.radio-group {
+    display: flex;
+    gap: 1.25rem;
+    margin-top: 0.25rem;
+}
+
+.radio-label {
+    display: flex;
+    align-items: center;
+    gap: 0.4rem;
+    cursor: pointer;
+    font-size: 0.9rem;
+    color: #374151;
+}
+
+/* Appearance Preview */
+.appearance-preview {
+    border: 1px solid #e2e8f0;
+    border-radius: 8px;
+    margin: 1.5rem 0;
+    overflow: hidden;
+}
+
+.preview-header {
+    padding: 0.5rem 1rem;
+    font-size: 0.8rem;
+    font-weight: 600;
+    text-transform: uppercase;
+    letter-spacing: 0.05em;
+    background: #f8fafc;
+    color: #64748b;
+    border-bottom: 1px solid #e2e8f0;
+}
+
+.preview-content {
+    padding: 1.25rem;
+}
+
+.preview-title {
+    font-weight: 600;
+    margin: 0 0 0.5rem;
+}
+
+.preview-text {
+    margin: 0 0 1rem;
+    color: #475569;
+}
+
+.preview-card {
+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+    padding: 0.5rem 0.75rem;
+    border: 1px solid #e2e8f0;
+    border-radius: 6px;
+    font-size: 0.85rem;
+}
+
+.preview-badge {
+    background: #2563eb;
+    color: #fff;
+    font-size: 0.7rem;
+    padding: 0.1rem 0.4rem;
+    border-radius: 3px;
+}
+
+/* Theme variants */
+.preview-theme-dark {
+    background: #1e293b;
+    color: #f1f5f9;
+}
+
+.preview-theme-dark .preview-header {
+    background: #0f172a;
+    color: #94a3b8;
+    border-color: #334155;
+}
+
+.preview-theme-dark .preview-text {
+    color: #94a3b8;
+}
+
+.preview-theme-dark .preview-card {
+    border-color: #334155;
+    background: #0f172a;
+}
+
+.preview-theme-light {
+    background: #ffffff;
+    color: #1e293b;
+}
+
+.preview-theme-system {
+    background: linear-gradient(135deg, #ffffff 50%, #1e293b 50%);
+    color: #1e293b;
+}
+
+/* Font size variants */
+.preview-font-small .preview-content { font-size: 0.8rem; }
+.preview-font-medium .preview-content { font-size: 0.95rem; }
+.preview-font-large .preview-content { font-size: 1.1rem; }
+
+/* Compact mode */
+.appearance-preview.compact .preview-content {
+    padding: 0.75rem;
+    line-height: 1.3;
+}
+
+.appearance-preview.compact .preview-card {
+    padding: 0.3rem 0.5rem;
+}
+
+/* Loading */
+.loading-spinner {
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    height: 200px;
+    color: #6b7280;
+    font-size: 1rem;
+}
+

